Duration? decDuration(Object? v) {
  if (v == null) return null;
  final nDuration = niceDuration(v);
  if (nDuration != null) return nDuration;
  if (v is String) {
    return switch (v) {
      'Durations.short1' => Durations.short1,
      'Durations.short2' => Durations.short2,
      'Durations.short3' => Durations.short3,
      'Durations.short4' => Durations.short4,
      'Durations.medium1' => Durations.medium1,
      'Durations.medium2' => Durations.medium2,
      'Durations.medium3' => Durations.medium3,
      'Durations.medium4' => Durations.medium4,
      'Durations.long1' => Durations.long1,
      'Durations.long2' => Durations.long2,
      'Durations.long3' => Durations.long3,
      'Durations.long4' => Durations.long4,
      'Durations.extralong1' => Durations.extralong1,
      'Durations.extralong2' => Durations.extralong2,
      'Durations.extralong3' => Durations.extralong3,
      'Durations.extralong4' => Durations.extralong4,
      'zero' => Duration.zero,
      _ => fuseBad('Duration', v),
    };
  }
  final m = v as Map;
  switch (m[r'$']) {
    case null:
      return Duration(days: decInt(m['days']) ?? 0, hours: decInt(m['hours']) ?? 0, minutes: decInt(m['minutes']) ?? 0, seconds: decInt(m['seconds']) ?? 0, milliseconds: decInt(m['milliseconds']) ?? 0, microseconds: decInt(m['microseconds']) ?? 0);
  }
  return fuseBad('Duration', v);
}

sqflite.OpenDatabaseOptions? decOpenDatabaseOptions(Object? v) {
  if (v == null) return null;
  final m = v as Map;
  switch (m[r'$']) {
    case null:
      return sqflite.OpenDatabaseOptions(version: decInt(m['version']), readOnly: decBool(m['readOnly']) ?? false, singleInstance: decBool(m['singleInstance']) ?? true, rollbackActiveTransactionOnOpen: decBool(m['rollbackActiveTransactionOnOpen']));
